"use client";

import React, { useState } from 'react';
import {
  Settings,
  Store,
  Truck,
  IndianRupee,
  MapPin,
  Save,
  CheckCircle2,
  ToggleLeft,
  ToggleRight,
  Sparkles,
  Compass,
  CreditCard,
  Eye,
  EyeOff,
  ShieldCheck,
  Wallet,
  Building,
  Plus,
  Trash2,
  Check,
  X
} from 'lucide-react';

interface GatewayItem {
  id: string;
  name: string;
  keyId: string;
  secretKey: string;
  webhookSecret: string;
  isActive: boolean;
}

export default function StoreSettingsPage() {
  const [activeTab, setActiveTab] = useState<'store' | 'payments' | 'delivery'>('store');

  // Store General Info & Location
  const [isStoreOpen, setIsStoreOpen] = useState(true);
  const [storeName, setStoreName] = useState('Royal Bengal');
  const [storeAddress, setStoreAddress] = useState('Madhapur, Hyderabad');
  const [storeLatitude, setStoreLatitude] = useState(17.351452);
  const [storeLongitude, setStoreLongitude] = useState(78.391039);

  // Payment Gateways Roster
  const [gateways, setGateways] = useState<GatewayItem[]>([
    {
      id: 'razorpay',
      name: 'Razorpay Gateway',
      keyId: 'rzp_test_TtDnHhPLVc92Ax',
      secretKey: 'QzicfCA9xInraYkNgffSUJb3',
      webhookSecret: 'QzicfCA9xInraYkNgffSUJb3',
      isActive: true,
    },
    {
      id: 'phonepe',
      name: 'PhonePe PG',
      keyId: 'MERCHANT_PHONEPE_102',
      secretKey: 'PPE_SECRET_99812',
      webhookSecret: 'PPE_WEBHOOK_001',
      isActive: false,
    },
    {
      id: 'paytm',
      name: 'Paytm Business',
      keyId: 'PAYTM_MID_55210',
      secretKey: 'PAYTM_SECRET_881',
      webhookSecret: 'PAYTM_WH_001',
      isActive: false,
    }
  ]);

  const [enableCod, setEnableCod] = useState(false);
  const [showSecretMap, setShowSecretMap] = useState<Record<string, boolean>>({});

  // Add Gateway Modal Form
  const [showAddGatewayModal, setShowAddGatewayModal] = useState(false);
  const [newGw, setNewGw] = useState({
    name: 'Stripe',
    keyId: '',
    secretKey: '',
    webhookSecret: '',
  });

  // Delivery Rule 1: Distance Radius
  const [enableRadiusFreeDelivery, setEnableRadiusFreeDelivery] = useState(true);
  const [maxFreeDeliveryRadiusKm, setMaxFreeDeliveryRadiusKm] = useState(5);
  const [feeOutsideRadius, setFeeOutsideRadius] = useState(60);

  // Delivery Rule 2: Order Value
  const [enableOrderValueFreeDelivery, setEnableOrderValueFreeDelivery] = useState(true);
  const [minOrderValueForFreeDelivery, setMinOrderValueForFreeDelivery] = useState(700);

  // General Fees
  const [minOrderSubtotal, setMinOrderSubtotal] = useState(0);

  const handleActivateGateway = (id: string) => {
    setGateways(prev => prev.map(gw => ({
      ...gw,
      isActive: gw.id === id
    })));
  };

  const handleUpdateGatewayKey = (id: string, field: keyof GatewayItem, value: any) => {
    setGateways(prev => prev.map(gw => {
      if (gw.id === id) {
        return { ...gw, [field]: value };
      }
      return gw;
    }));
  };

  const handleDeleteGateway = (id: string) => {
    if (gateways.length <= 1) return alert("At least one payment gateway must remain configured.");
    if (confirm("Delete this payment gateway provider?")) {
      setGateways(prev => prev.filter(gw => gw.id !== id));
    }
  };

  const handleAddGatewaySubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newGw.name.trim() || !newGw.keyId.trim()) return alert("Please fill in gateway name and key ID.");

    const id = newGw.name.toLowerCase().replace(/\s+/g, '_') + '_' + Date.now().toString().slice(-4);
    const created: GatewayItem = {
      id,
      name: newGw.name,
      keyId: newGw.keyId,
      secretKey: newGw.secretKey,
      webhookSecret: newGw.webhookSecret,
      isActive: false,
    };

    setGateways([...gateways, created]);
    setShowAddGatewayModal(false);
    setNewGw({ name: 'Stripe', keyId: '', secretKey: '', webhookSecret: '' });
  };

  const activeGw = gateways.find(g => g.isActive) || gateways[0];

  return (
    <div className="space-y-6 max-w-4xl mx-auto relative">

      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-xl font-semibold text-[#1a1a1a]">Store Settings</h1>
          <p className="text-[13px] text-[#616161] mt-0.5">Manage store open status, payment gateways, API keys, and delivery fee policies.</p>
        </div>
      </div>

      {/* HORIZONTAL SETTINGS TAB NAVIGATION */}
      <div className="bg-white p-1.5 rounded-xl border border-gray-200 shadow-sm flex flex-wrap gap-1">
        {[
          { id: 'store', label: 'Store status & location', icon: Store },
          { id: 'payments', label: 'Payment gateways & API keys', icon: CreditCard },
          { id: 'delivery', label: 'Delivery & shipping', icon: Truck },
        ].map(tab => {
          const Icon = tab.icon;
          const isActive = activeTab === tab.id;

          return (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id as any)}
              className={`flex-1 min-w-[150px] px-3.5 h-9 rounded-lg text-xs font-medium transition-colors flex items-center justify-center gap-2 ${
                isActive
                  ? 'bg-[#303030] text-white font-semibold shadow-xs'
                  : 'text-[#616161] hover:text-[#1a1a1a] hover:bg-[#f7f7f7]'
              }`}
            >
              <Icon size={15} />
              <span>{tab.label}</span>
            </button>
          );
        })}
      </div>

      {/* TAB 1: STORE STATUS, IDENTITY & GPS LOCATION */}
      {activeTab === 'store' && (
        <div className="bg-white p-6 rounded-xl shadow-[0_0_0_1px_rgba(0,0,0,0.06),0_1px_2px_rgba(0,0,0,0.04)] space-y-5 animate-in fade-in duration-200 text-xs">

          {/* Store Open/Closed Master Switch */}
          <div className="flex items-center justify-between border-b border-gray-100 pb-4">
            <div>
              <h2 className="text-sm font-semibold text-[#1a1a1a]">Store open / closed status</h2>
              <p className="text-xs text-[#616161] mt-0.5">Master toggle controlling whether the customer storefront accepts live orders.</p>
            </div>

            <button
              type="button"
              onClick={() => setIsStoreOpen(!isStoreOpen)}
              className={`flex items-center gap-2 px-3.5 h-9 rounded-lg text-xs font-medium border transition-colors ${
                isStoreOpen
                  ? 'bg-[#cdfed4] text-[#014b40] border-emerald-200'
                  : 'bg-[#fed1d7] text-[#8e0b21] border-rose-200'
              }`}
            >
              {isStoreOpen ? <ToggleRight size={20} /> : <ToggleLeft size={20} />}
              <span>{isStoreOpen ? 'Store open' : 'Store closed'}</span>
            </button>
          </div>

          {/* Store Name & Address */}
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div>
              <label className="font-medium text-[#616161] block mb-1">Store name</label>
              <input
                type="text"
                value={storeName}
                onChange={e => setStoreName(e.target.value)}
                className="w-full bg-[#f7f7f7] border border-gray-200 rounded-lg p-2.5 text-xs text-[#1a1a1a] outline-none"
              />
            </div>

            <div>
              <label className="font-medium text-[#616161] block mb-1">Store address / hub</label>
              <input
                type="text"
                value={storeAddress}
                onChange={e => setStoreAddress(e.target.value)}
                className="w-full bg-[#f7f7f7] border border-gray-200 rounded-lg p-2.5 text-xs text-[#1a1a1a] outline-none"
              />
            </div>
          </div>

          {/* Dark Store GPS Coordinates */}
          <div className="pt-3 border-t border-gray-100 space-y-3">
            <div>
              <h3 className="text-xs font-semibold text-[#1a1a1a]">Dark store hub GPS location</h3>
              <p className="text-[11px] text-[#616161]">Used for Haversine distance calculations from store hub to customer map pin.</p>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div>
                <label className="font-medium text-[#616161] block mb-1">Store latitude</label>
                <input
                  type="number"
                  step="0.000001"
                  value={storeLatitude}
                  onChange={e => setStoreLatitude(Number(e.target.value))}
                  className="w-full bg-[#f7f7f7] border border-gray-200 rounded-lg p-2.5 text-xs text-[#1a1a1a] outline-none"
                />
              </div>

              <div>
                <label className="font-medium text-[#616161] block mb-1">Store longitude</label>
                <input
                  type="number"
                  step="0.000001"
                  value={storeLongitude}
                  onChange={e => setStoreLongitude(Number(e.target.value))}
                  className="w-full bg-[#f7f7f7] border border-gray-200 rounded-lg p-2.5 text-xs text-[#1a1a1a] outline-none"
                />
              </div>
            </div>
          </div>

        </div>
      )}

      {/* TAB 2: DYNAMIC PAYMENT GATEWAYS & KEYS MANAGER */}
      {activeTab === 'payments' && (
        <div className="space-y-5 animate-in fade-in duration-200 text-xs">

          {/* Header Action Bar */}
          <div className="bg-white p-5 rounded-xl shadow-[0_0_0_1px_rgba(0,0,0,0.06),0_1px_2px_rgba(0,0,0,0.04)] flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
            <div>
              <div className="flex items-center gap-2">
                <h2 className="text-sm font-semibold text-[#1a1a1a]">Configured Payment Gateways</h2>
                <span className="inline-flex items-center px-2.5 h-5 rounded-full text-[11px] font-medium bg-[#cdfed4] text-[#014b40]">
                  Active: {activeGw?.name || 'Razorpay'}
                </span>
              </div>
              <p className="text-xs text-[#616161] mt-0.5">Add custom payment gateways and update API keys for live checkout.</p>
            </div>

            <button
              type="button"
              onClick={() => setShowAddGatewayModal(true)}
              className="bg-[#303030] hover:bg-[#1a1a1a] text-white px-3.5 h-9 rounded-lg text-xs font-medium inline-flex items-center gap-1.5 transition-colors shrink-0"
            >
              <Plus size={15} /> Add payment gateway
            </button>
          </div>

          {/* GATEWAYS LIST */}
          <div className="space-y-4">
            {gateways.map((gw) => {
              const isVisibleSecret = !!showSecretMap[gw.id];

              return (
                <div
                  key={gw.id}
                  className={`bg-white p-6 rounded-xl shadow-[0_0_0_1px_rgba(0,0,0,0.06),0_1px_2px_rgba(0,0,0,0.04)] space-y-4 border-l-4 ${
                    gw.isActive ? 'border-l-[#014b40]' : 'border-l-gray-300'
                  }`}
                >

                  {/* Top Gateway Info & Activate Switch */}
                  <div className="flex items-center justify-between border-b border-gray-100 pb-3">
                    <div className="flex items-center gap-3">
                      <div className="w-10 h-10 rounded-lg bg-[#303030] text-white flex items-center justify-center font-semibold shrink-0">
                        <CreditCard size={18} />
                      </div>
                      <div>
                        <div className="flex items-center gap-2">
                          <h3 className="text-sm font-semibold text-[#1a1a1a]">{gw.name}</h3>
                          {gw.isActive && (
                            <span className="inline-flex items-center px-2 h-5 rounded-full text-[10px] font-medium bg-[#cdfed4] text-[#014b40]">
                              Live active provider
                            </span>
                          )}
                        </div>
                        <span className="text-[11px] text-[#8a8a8a]">Provider ID: {gw.id}</span>
                      </div>
                    </div>

                    <div className="flex items-center gap-2">
                      <button
                        type="button"
                        onClick={() => handleActivateGateway(gw.id)}
                        className={`px-3 h-8 rounded-lg text-xs font-medium border transition-colors flex items-center gap-1.5 ${
                          gw.isActive
                            ? 'bg-[#cdfed4] text-[#014b40] border-emerald-200'
                            : 'bg-[#f7f7f7] text-[#303030] border-gray-200 hover:bg-gray-100'
                        }`}
                      >
                        {gw.isActive ? <Check size={14} /> : null}
                        <span>{gw.isActive ? 'Active provider' : 'Set as active'}</span>
                      </button>

                      <button
                        type="button"
                        onClick={() => handleDeleteGateway(gw.id)}
                        className="p-1.5 text-gray-400 hover:text-red-600 rounded-lg hover:bg-rose-50 transition-colors"
                        title="Delete Gateway"
                      >
                        <Trash2 size={16} />
                      </button>
                    </div>
                  </div>

                  {/* Key Inputs */}
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                    <div>
                      <label className="font-medium text-[#616161] block mb-1">Merchant / Key ID</label>
                      <input
                        type="text"
                        value={gw.keyId}
                        onChange={e => handleUpdateGatewayKey(gw.id, 'keyId', e.target.value)}
                        className="w-full bg-[#f7f7f7] border border-gray-200 rounded-lg p-2.5 text-xs text-[#1a1a1a] outline-none"
                        placeholder="Key ID / Merchant ID..."
                      />
                    </div>

                    <div>
                      <label className="font-medium text-[#616161] block mb-1">Secret Key</label>
                      <div className="relative">
                        <input
                          type={isVisibleSecret ? "text" : "password"}
                          value={gw.secretKey}
                          onChange={e => handleUpdateGatewayKey(gw.id, 'secretKey', e.target.value)}
                          className="w-full bg-[#f7f7f7] border border-gray-200 rounded-lg pl-2.5 pr-9 py-2.5 text-xs text-[#1a1a1a] outline-none"
                          placeholder="Secret Key..."
                        />
                        <button
                          type="button"
                          onClick={() => setShowSecretMap({ ...showSecretMap, [gw.id]: !isVisibleSecret })}
                          className="absolute right-2.5 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600"
                        >
                          {isVisibleSecret ? <EyeOff size={15} /> : <Eye size={15} />}
                        </button>
                      </div>
                    </div>
                  </div>

                  {/* Webhook Secret */}
                  <div>
                    <label className="font-medium text-[#616161] block mb-1">Webhook Signing Secret</label>
                    <input
                      type="password"
                      value={gw.webhookSecret}
                      onChange={e => handleUpdateGatewayKey(gw.id, 'webhookSecret', e.target.value)}
                      className="w-full bg-[#f7f7f7] border border-gray-200 rounded-lg p-2.5 text-xs text-[#1a1a1a] outline-none max-w-md"
                      placeholder="Webhook HMAC Secret..."
                    />
                  </div>

                </div>
              );
            })}
          </div>

          {/* COD Toggle */}
          <div className="bg-white p-5 rounded-xl shadow-[0_0_0_1px_rgba(0,0,0,0.06),0_1px_2px_rgba(0,0,0,0.04)] flex items-center justify-between">
            <div>
              <span className="text-xs font-semibold text-[#1a1a1a] block">Cash on Delivery (COD)</span>
              <span className="text-[#616161]">Allow customers to pay in cash upon doorstep delivery.</span>
            </div>

            <button
              type="button"
              onClick={() => setEnableCod(!enableCod)}
              className={`flex items-center gap-1.5 px-3 h-8 rounded-lg text-xs font-medium border transition-colors ${
                enableCod ? 'bg-[#cdfed4] text-[#014b40] border-emerald-200' : 'bg-[#e3e3e3] text-[#303030] border-gray-200'
              }`}
            >
              {enableCod ? <ToggleRight size={18} /> : <ToggleLeft size={18} />}
              <span>{enableCod ? 'COD enabled' : 'COD disabled'}</span>
            </button>
          </div>

        </div>
      )}

      {/* TAB 3: DELIVERY & SHIPPING RULES */}
      {activeTab === 'delivery' && (
        <div className="space-y-4 animate-in fade-in duration-200 text-xs">

          {/* Policy Summary Box */}
          <div className="bg-[#303030] text-white p-5 rounded-xl shadow-sm space-y-1">
            <span className="text-[11px] font-semibold text-gray-300 uppercase tracking-wider block">Active Policy Preview</span>
            <p className="text-xs font-medium leading-relaxed">
              {enableRadiusFreeDelivery && enableOrderValueFreeDelivery ? (
                <>
                  Free delivery within <span className="font-semibold text-white">{maxFreeDeliveryRadiusKm} KM</span>. Outside {maxFreeDeliveryRadiusKm} KM, orders $\ge$ <span className="font-semibold text-white">₹{minOrderValueForFreeDelivery}</span> get free delivery (otherwise ₹{feeOutsideRadius} fee applies).
                </>
              ) : (
                <>Standard delivery fee of ₹{feeOutsideRadius} applies.</>
              )}
            </p>
          </div>

          {/* Distance Radius Rule Card */}
          <div className="bg-white p-6 rounded-xl shadow-[0_0_0_1px_rgba(0,0,0,0.06),0_1px_2px_rgba(0,0,0,0.04)] space-y-4">
            <div className="flex items-center justify-between border-b border-gray-100 pb-3">
              <div>
                <h2 className="text-sm font-semibold text-[#1a1a1a]">Distance radius free delivery</h2>
                <p className="text-xs text-[#616161]">Offer free delivery within a specific kilometer radius from store hub.</p>
              </div>

              <button
                type="button"
                onClick={() => setEnableRadiusFreeDelivery(!enableRadiusFreeDelivery)}
                className={`px-3 h-8 rounded-lg text-xs font-medium border transition-colors ${
                  enableRadiusFreeDelivery ? 'bg-[#cdfed4] text-[#014b40] border-emerald-200' : 'bg-[#e3e3e3] text-[#303030] border-gray-200'
                }`}
              >
                {enableRadiusFreeDelivery ? 'Enabled' : 'Disabled'}
              </button>
            </div>

            {enableRadiusFreeDelivery && (
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div>
                  <label className="font-medium text-[#616161] block mb-1">Free delivery radius (KM)</label>
                  <input
                    type="number"
                    value={maxFreeDeliveryRadiusKm}
                    onChange={e => setMaxFreeDeliveryRadiusKm(Number(e.target.value))}
                    className="w-full bg-[#f7f7f7] border border-gray-200 rounded-lg p-2.5 text-xs text-[#1a1a1a] outline-none font-semibold"
                  />
                </div>

                <div>
                  <label className="font-medium text-[#616161] block mb-1">Delivery fee outside radius (₹)</label>
                  <input
                    type="number"
                    value={feeOutsideRadius}
                    onChange={e => setFeeOutsideRadius(Number(e.target.value))}
                    className="w-full bg-[#f7f7f7] border border-gray-200 rounded-lg p-2.5 text-xs text-[#1a1a1a] outline-none font-semibold"
                  />
                </div>
              </div>
            )}
          </div>

          {/* Order Value Rule Card */}
          <div className="bg-white p-6 rounded-xl shadow-[0_0_0_1px_rgba(0,0,0,0.06),0_1px_2px_rgba(0,0,0,0.04)] space-y-4">
            <div className="flex items-center justify-between border-b border-gray-100 pb-3">
              <div>
                <h2 className="text-sm font-semibold text-[#1a1a1a]">Order value free delivery</h2>
                <p className="text-xs text-[#616161]">Offer free delivery on orders meeting a minimum subtotal threshold.</p>
              </div>

              <button
                type="button"
                onClick={() => setEnableOrderValueFreeDelivery(!enableOrderValueFreeDelivery)}
                className={`px-3 h-8 rounded-lg text-xs font-medium border transition-colors ${
                  enableOrderValueFreeDelivery ? 'bg-[#cdfed4] text-[#014b40] border-emerald-200' : 'bg-[#e3e3e3] text-[#303030] border-gray-200'
                }`}
              >
                {enableOrderValueFreeDelivery ? 'Enabled' : 'Disabled'}
              </button>
            </div>

            {enableOrderValueFreeDelivery && (
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div>
                  <label className="font-medium text-[#616161] block mb-1">Minimum order value for free delivery (₹)</label>
                  <input
                    type="number"
                    value={minOrderValueForFreeDelivery}
                    onChange={e => setMinOrderValueForFreeDelivery(Number(e.target.value))}
                    className="w-full bg-[#f7f7f7] border border-gray-200 rounded-lg p-2.5 text-xs text-[#1a1a1a] outline-none font-semibold"
                  />
                </div>

                <div>
                  <label className="font-medium text-[#616161] block mb-1">Minimum order subtotal to allow checkout (₹)</label>
                  <input
                    type="number"
                    value={minOrderSubtotal}
                    onChange={e => setMinOrderSubtotal(Number(e.target.value))}
                    className="w-full bg-[#f7f7f7] border border-gray-200 rounded-lg p-2.5 text-xs text-[#1a1a1a] outline-none font-semibold"
                  />
                </div>
              </div>
            )}
          </div>

        </div>
      )}

      {/* ADD GATEWAY MODAL */}
      {showAddGatewayModal && (
        <div className="fixed inset-0 bg-black/40 backdrop-blur-xs z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-xl max-w-md w-full p-6 space-y-4 shadow-xl text-xs animate-in zoom-in-95 duration-200">
            <div className="flex justify-between items-center border-b border-gray-100 pb-3">
              <h3 className="font-semibold text-[#1a1a1a] text-sm">Add Payment Gateway Provider</h3>
              <button onClick={() => setShowAddGatewayModal(false)} className="text-gray-400 hover:text-gray-600"><X size={18} /></button>
            </div>

            <form onSubmit={handleAddGatewaySubmit} className="space-y-3">
              <div>
                <label className="font-medium text-[#616161] block mb-1">Gateway Provider Name</label>
                <input
                  required
                  type="text"
                  value={newGw.name}
                  onChange={e => setNewGw({ ...newGw, name: e.target.value })}
                  className="w-full bg-[#f7f7f7] border border-gray-200 rounded-lg p-2.5 text-xs text-[#1a1a1a] outline-none font-medium"
                  placeholder="e.g. Stripe, Instamojo, PayU"
                />
              </div>

              <div>
                <label className="font-medium text-[#616161] block mb-1">Merchant / Key ID</label>
                <input
                  required
                  type="text"
                  value={newGw.keyId}
                  onChange={e => setNewGw({ ...newGw, keyId: e.target.value })}
                  className="w-full bg-[#f7f7f7] border border-gray-200 rounded-lg p-2.5 text-xs text-[#1a1a1a] outline-none font-medium"
                  placeholder="Key ID / Publishable Key..."
                />
              </div>

              <div>
                <label className="font-medium text-[#616161] block mb-1">Secret Key</label>
                <input
                  type="password"
                  value={newGw.secretKey}
                  onChange={e => setNewGw({ ...newGw, secretKey: e.target.value })}
                  className="w-full bg-[#f7f7f7] border border-gray-200 rounded-lg p-2.5 text-xs text-[#1a1a1a] outline-none font-medium"
                  placeholder="Secret Key..."
                />
              </div>

              <div>
                <label className="font-medium text-[#616161] block mb-1">Webhook Secret</label>
                <input
                  type="password"
                  value={newGw.webhookSecret}
                  onChange={e => setNewGw({ ...newGw, webhookSecret: e.target.value })}
                  className="w-full bg-[#f7f7f7] border border-gray-200 rounded-lg p-2.5 text-xs text-[#1a1a1a] outline-none font-medium"
                  placeholder="Webhook Signing Secret..."
                />
              </div>

              <div className="flex gap-2 pt-2">
                <button
                  type="button"
                  onClick={() => setShowAddGatewayModal(false)}
                  className="flex-1 py-2.5 border border-gray-200 rounded-lg font-medium text-xs text-gray-600 hover:bg-gray-50"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  className="flex-1 py-2.5 bg-[#303030] hover:bg-[#1a1a1a] text-white font-medium rounded-lg text-xs transition-colors"
                >
                  Add Gateway
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

    </div>
  );
}
